-- MaxGio Health EHR schema. Target: Hostinger MySQL/MariaDB (u986504880_maxgioEHR_db).
-- Run with: npm run migrate   (idempotent: every statement uses IF NOT EXISTS)
-- IDs are UUIDs (CHAR(36)) generated by the app (crypto.randomUUID()) so they are
-- not guessable/enumerable. All timestamps are stored in UTC.
-- Columns ending in _enc hold application-encrypted values (AES-256-GCM, base64).

CREATE TABLE IF NOT EXISTS users (
  id              CHAR(36)     NOT NULL,
  email           VARCHAR(255) NOT NULL,
  password_hash   VARCHAR(255) NOT NULL,
  role            ENUM('admin','provider','staff','patient') NOT NULL DEFAULT 'staff',
  first_name      VARCHAR(100) NOT NULL,
  last_name       VARCHAR(100) NOT NULL,
  is_active       TINYINT(1)   NOT NULL DEFAULT 1,
  failed_logins   INT UNSIGNED NOT NULL DEFAULT 0,
  locked_until    DATETIME     NULL,
  must_change_password TINYINT(1) NOT NULL DEFAULT 0,  -- true while using a temporary password
  tokens_valid_after DATETIME  NULL,                 -- sessions issued before this are rejected
  last_login_at   DATETIME     NULL,
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email),
  KEY idx_users_role (role)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS patients (
  id              CHAR(36)     NOT NULL,
  user_id         CHAR(36)     NULL,                 -- set if the patient has a portal login
  mrn             VARCHAR(32)  NOT NULL,             -- medical record number
  first_name      VARCHAR(100) NOT NULL,
  last_name       VARCHAR(100) NOT NULL,
  date_of_birth   DATE         NOT NULL,
  sex             ENUM('female','male','other','unknown') NOT NULL DEFAULT 'unknown',
  email           VARCHAR(255) NULL,
  phone           VARCHAR(40)  NULL,
  address_enc     TEXT         NULL,                 -- encrypted
  ssn_enc         TEXT         NULL,                 -- encrypted
  allergies_enc   TEXT         NULL,                 -- encrypted
  medical_notes_enc MEDIUMTEXT NULL,                 -- encrypted
  primary_provider_id CHAR(36) NULL,
  is_active       TINYINT(1)   NOT NULL DEFAULT 1,
  created_by      CHAR(36)     NULL,
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_patients_mrn (mrn),
  KEY idx_patients_name (last_name, first_name),
  KEY idx_patients_provider (primary_provider_id),
  CONSTRAINT fk_patients_user     FOREIGN KEY (user_id)             REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_patients_provider FOREIGN KEY (primary_provider_id) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT fk_patients_creator  FOREIGN KEY (created_by)          REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS appointments (
  id              CHAR(36)     NOT NULL,
  patient_id      CHAR(36)     NOT NULL,
  provider_id     CHAR(36)     NOT NULL,
  starts_at       DATETIME     NOT NULL,             -- UTC
  ends_at         DATETIME     NOT NULL,             -- UTC
  type            ENUM('in_person','telehealth') NOT NULL DEFAULT 'in_person',
  status          ENUM('scheduled','checked_in','completed','cancelled','no_show') NOT NULL DEFAULT 'scheduled',
  reason          VARCHAR(500) NULL,
  telehealth_room_id VARCHAR(64) NULL,               -- link = TELEHEALTH_BASE_URL/<room id>
  created_by      CHAR(36)     NULL,
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_appt_room (telehealth_room_id),
  KEY idx_appt_patient (patient_id, starts_at),
  KEY idx_appt_provider (provider_id, starts_at),
  KEY idx_appt_status (status),
  CONSTRAINT fk_appt_patient  FOREIGN KEY (patient_id)  REFERENCES patients (id) ON DELETE CASCADE,
  CONSTRAINT fk_appt_provider FOREIGN KEY (provider_id) REFERENCES users (id)    ON DELETE RESTRICT,
  CONSTRAINT fk_appt_creator  FOREIGN KEY (created_by)  REFERENCES users (id)    ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Clinical notes / encounters (encrypted body).
CREATE TABLE IF NOT EXISTS encounters (
  id              CHAR(36)     NOT NULL,
  patient_id      CHAR(36)     NOT NULL,
  provider_id     CHAR(36)     NOT NULL,
  appointment_id  CHAR(36)     NULL,
  encounter_at    DATETIME     NOT NULL,
  summary         VARCHAR(500) NULL,
  note_enc        MEDIUMTEXT   NULL,                 -- encrypted
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_enc_patient (patient_id, encounter_at),
  CONSTRAINT fk_enc_patient  FOREIGN KEY (patient_id)     REFERENCES patients (id)     ON DELETE CASCADE,
  CONSTRAINT fk_enc_provider FOREIGN KEY (provider_id)    REFERENCES users (id)        ON DELETE RESTRICT,
  CONSTRAINT fk_enc_appt     FOREIGN KEY (appointment_id) REFERENCES appointments (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- JWT revocation (logout / forced sign-out). Rows can be purged after expires_at.
CREATE TABLE IF NOT EXISTS revoked_tokens (
  jti             CHAR(36)     NOT NULL,
  user_id         CHAR(36)     NULL,
  expires_at      DATETIME     NOT NULL,
  revoked_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (jti),
  KEY idx_revoked_expires (expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Append-only audit trail: who touched which record, when, from where.
CREATE TABLE IF NOT EXISTS audit_log (
  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id         CHAR(36)     NULL,
  action          VARCHAR(50)  NOT NULL,             -- e.g. login, patient.read, patient.update
  entity_type     VARCHAR(50)  NULL,
  entity_id       CHAR(36)     NULL,
  ip_address      VARCHAR(45)  NULL,
  user_agent      VARCHAR(255) NULL,
  details         JSON         NULL,                 -- never put PHI values here
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_audit_user (user_id, created_at),
  KEY idx_audit_entity (entity_type, entity_id),
  KEY idx_audit_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Non-secret runtime settings editable without a redeploy (secrets stay in .env).
CREATE TABLE IF NOT EXISTS settings (
  `key`           VARCHAR(100) NOT NULL,
  `value`         TEXT         NOT NULL,
  updated_by      CHAR(36)     NULL,
  updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
